document.addEventListener("DOMContentLoaded",()=>{const t=()=>{const t=document.querySelector("#the-list");t&&t.querySelectorAll(".nf-submissions-cell").forEach(t=>{if(t&&t.dataset&&"1"===t.dataset.godamProcessed)return;const e=t.textContent.trim();if((e.startsWith("http://")||e.startsWith("https://"))&&e.includes("/wp-content/uploads/")){let n;try{n=new URL(e,window.location.origin)}catch(t){return}if(("http:"===n.protocol||"https:"===n.protocol)&&n.origin===window.location.origin){const e=document.createElement("a");e.href=n.href,e.target="_blank",e.rel="noopener noreferrer",e.textContent="View Recording",t.textContent="",t.appendChild(e),t.dataset.godamProcessed="1"}}})};t(),new MutationObserver(()=>{t()}).observe(document.getElementById("nf-submissions-element"),{childList:!0,subtree:!0})});